(function () {
  "use strict";
  // Layer JS loads on every page: it does nothing without a workbench.
  var workbench = document.querySelector("[data-studio-workbench]");
  if (!workbench) {
    return;
  }
  // studio.js (studio:studio, order 0) runs first and gives the API.
  var S = window.ScrudStudio;
  if (!S) return;

  // The branch settings pane: T's own resource, embedded by studio:workbench
  // in the scope studio studio-branch (in view mode when T is published).
  // Its prefix input is rendered only in the scope studio studio-branch
  // studio-publish, which this script asks for when the strip says the user
  // may publish (`may_publish`: PUT on UI branches in the context ""). The
  // scope only presents: a save without the grant is refused by the API.
  // studio.js keeps its fields from saving on change: Save does.
  var SCOPE = "studio studio-branch";
  var PUBLISH_SCOPE = "studio studio-branch studio-publish";
  var pane = workbench.querySelector('[data-studio-embed="branch"]');
  if (!pane) return;

  function strip() {
    return workbench.querySelector('[data-studio-embed="status"]');
  }

  function stripSays(name) {
    var status = workbench.querySelector("[data-studio-status]");
    return status ? status.getAttribute(name) : null;
  }

  // The scope and mode the pane is wanted in, as the strip tells them.
  function wanted() {
    var publish = stripSays("data-studio-may-publish") === "true" && S.branch !== "main";
    return { scope: publish ? PUBLISH_SCOPE : SCOPE, view: S.published && !publish };
  }

  // Fetch the pane again in `want`'s scope and mode (scrud-ui.js adds the
  // branch and safe mode).
  function load(want) {
    var htmx = window.htmx;
    if (!htmx || typeof htmx.ajax !== "function") return;
    pane.setAttribute("data-studio-scope", want.scope);
    if (want.view) pane.setAttribute("data-studio-mode", "view");
    else pane.removeAttribute("data-studio-mode");
    var headers = { "Scrud-UI-Scope": want.scope };
    if (want.view) headers["Scrud-UI-Mode"] = "view";
    htmx.ajax("GET", pane.getAttribute("data-studio-src"), {
      source: pane,
      target: pane,
      swap: "innerHTML",
      headers: headers
    });
  }

  function settings() {
    return pane.querySelector(".scrud-resource");
  }

  // What is typed in the settings and not saved counts as the workbench's.
  S.watchUnsaved(function () {
    return S.frameChanged(settings());
  });

  function reload() {
    window.location.reload();
  }

  // On load and whenever the strip is fetched again. T published, or no
  // longer (by a save of its prefix), changes what the whole workbench
  // offers: it is loaded again, but never under unsaved input (the
  // editor's, the settings', a new rule's): the notice then asks for it.
  function sync() {
    var published = stripSays("data-studio-published");
    if (published !== null && (published === "true") !== S.published) {
      if (!S.unsaved()) {
        reload();
        return;
      }
      S.notify(
        "This branch was " +
          (published === "true" ? "published" : "unpublished") +
          ": reload the workbench for what it offers now. Save your unsaved" +
          " changes first, or they are lost.",
        "Reload",
        reload
      );
      return;
    }
    var want = wanted();
    var view = pane.getAttribute("data-studio-mode") === "view";
    if (want.scope !== pane.getAttribute("data-studio-scope") || want.view !== view) {
      load(want);
    }
  }

  // The frame's Delete of a published T (not main, which can't be deleted)
  // takes the site's URLs under its prefix away: it asks with that, not the
  // runtime's "Delete?". The prefix is the frame's content's.
  function decorateDelete() {
    var frame = pane.querySelector(".scrud-resource");
    if (!frame || !S.published || S.branch === "main") return;
    var href = frame.getAttribute("data-scrud-href");
    var content = S.contentOf(frame);
    var prefix = content && typeof content.prefix === "string" ? content.prefix : "";
    var text =
      "Delete the published branch " +
      S.branch +
      "? " +
      (prefix
        ? "It is published at " +
          prefix +
          ": deleting it takes away the site's URLs under that prefix."
        : "Deleting it takes away the site's URLs under its prefix.");
    var buttons = frame.querySelectorAll("button[hx-delete]");
    for (var i = 0; i < buttons.length; i++) {
      if (buttons[i].getAttribute("hx-delete") !== href) continue;
      if (buttons[i].closest(".scrud-resource") !== frame) continue;
      buttons[i].setAttribute("hx-confirm", text);
    }
  }

  document.addEventListener("htmx:afterSwap", function (evt) {
    if (evt.target && evt.target === strip()) sync();
    if (evt.target && (evt.target === pane || pane.contains(evt.target))) decorateDelete();
  });

  // A write from the strip (a pull, a push) changes T's row: the settings
  // are fetched again, with its new ETag. Not under what was typed in them:
  // the notice then says their Save is stale, with a button that fetches
  // them again. Any other write leaves them alone.
  document.addEventListener("htmx:afterRequest", function (evt) {
    var detail = evt.detail || {};
    var verb = String((detail.requestConfig || {}).verb || "").toLowerCase();
    if (!detail.successful || !verb || verb === "get") return;
    var status = strip();
    if (!status || !evt.target || !status.contains(evt.target)) return;
    if (!S.frameChanged(settings())) {
      load(wanted());
      return;
    }
    S.notify(
      "This branch changed since its settings were loaded: they keep what you" +
        " typed, but their Save is refused until they are loaded again.",
      "Reload settings",
      function () {
        S.clearNotice();
        load(wanted());
      }
    );
  });

  // T deleted from its settings (the frame's Delete): the workbench is
  // loaded again, and says it is gone.
  document.addEventListener("scrud:deleted", function (evt) {
    var href = evt.detail && evt.detail.href;
    if (href && href === pane.getAttribute("data-studio-src")) window.location.reload();
  });

  decorateDelete();
  sync();
})();
